n// unset all\n\n@mixin unset-all {\n  top: unset;\n  right: unset;\n  bottom: unset;\n  left: unset;\n}\n\n// absolute\n\n@mixin absolute(\n  $top: null,\n  $right: null,\n  $bottom: null,\n  $left: null,\n  $x: null,\n  $y: null,\n  $all: null,\n) {\n  @include -position(\n    $position: absolute,\n    $top: if($top, $top, if($y, $y, $all)),\n    $right: if($right, $right, if($x, $x, $all)),\n    $bottom: if($bottom, $bottom, if($y, $y, $all)),\n    $left: if($left, $left, if($x, $x, $all)),\n  );\n}\n\n@mixin absolute-xy($x: null, $y: null) {\n  @include absolute($x: $x, $y: $y);\n}\n\n@mixin absolute-axis($horizontal: null, $vertical: null) {\n  @include absolute($x: $horizontal, $y: $vertical);\n}\n\n@mixin absolute-all($margin) {\n  @include absolute($all: $margin);\n}\n\n@mixin absolute-square($margin) {\n  @include absolute($all: $margin);\n}\n\n@mixin absolute-fill {\n  @include absolute($all: 0);\n}\n\n@mixin absolute-anchor(\n  $x: null,\n  $y: null,\n  $x-prop: left,\n  $y-prop: top,\n) {\n  $translate-x: if($x, -$x, null);\n  $translate-y: if($y, -$y, null);\n\n  @if $translate-x and unit($translate-x) != '%' { // e.g., px\n    $translate-x: 0;\n  }\n\n  @if $translate-y and unit($translate-y) != '%' {\n    $translate-y: 0;\n  }\n\n  @include absolute(\n    $top: if($y-prop == top, $y, null),\n    $right: if($x-prop == right, $x, null),\n    $bottom: if($y-prop == bottom, $y, null),\n    $left: if($x-prop == left, $x, null),\n  );\n\n  @include translate($x: $translate-x, $y: $translate-y);\n}\n\n@mixin absolute-center($x-prop: left, $y-prop: top) {\n  @include absolute-anchor($x: 50%, $y: 50%, $x-prop: $x-prop, $y-prop: $y-prop);\n}\n\n// fixed\n\n@mixin fixed(\n  $top: null,\n  $right: null,\n  $bottom: null,\n  $left: null,\n  $x: null,\n  $y: null,\n  $all: null,\n) {\n  @include -position(\n    $position: fixed,\n    $top: if($top, $top, if($y, $y, $all)),\n    $right: if($right, $right, if($x, $x, $all)),\n    $bottom: if($bottom, $bottom, if($y, $y, $all)),\n    $left: if($left, $left, if($x, $x, $all)),\n  );\n}\n\n@mixin fixed-xy($x: null, $y: null) {\n  @include fixed($x: $x, $y: $y);\n}\n\n@mixin fixed-axis($horizontal: null, $vertical: null) {\n  @include fixed($x: $horizontal, $y: $vertical);\n}\n\n@mixin fixed-all($margin) {\n  @include fixed($all: $margin);\n}\n\n@mixin fixed-square($margin) {\n  @include fixed($all: $margin);\n}\n\n@mixin fixed-fill {\n  @include fixed($all: 0);\n}\n\n@mixin fixed-anchor(\n  $x: null,\n  $y: null,\n  $x-prop: left,\n  $y-prop: top,\n) {\n  $translate-x: if($x, -$x, null);\n  $translate-y: if($y, -$y, null);\n\n  @if $translate-x and unit($translate-x) != '%' {\n    $translate-x: 0;\n  }\n\n  @if $translate-y and unit($translate-y) != '%' {\n    $translate-y: 0;\n  }\n\n  @include fixed(\n    $top: if($y-prop == top, $y, null),\n    $right: if($x-prop == right, $x, null),\n    $bottom: if($y-prop == bottom, $y, null),\n    $left: if($x-prop == left, $x, null),\n  );\n\n  @include translate($x: $translate-x, $y: $translate-y);\n}\n\n@mixin fixed-center($x-prop: left, $y-prop: top) {\n  @include fixed-anchor($x: 50%, $y: 50%, $x-prop: $x-prop, $y-prop: $y-prop);\n}\n"],sourceRoot:""}]),a.locals={container:"BuildInfo-module-container--EXCs6",light:"BuildInfo-module-light--ZE3pS",dark:"BuildInfo-module-dark--J_zsG","top-left":"BuildInfo-module-top-left--LvAGA","top-right":"BuildInfo-module-top-right--sx8uq","bottom-right":"BuildInfo-module-bottom-right--Rn2Q7","bottom-left":"BuildInfo-module-bottom-left--ikrfS"},t.Z=a},634:function(e,t,n){"use strict";var o=n(7537),r=n.n(o),i=n(3645),a=n.n(i)()(r());a.push([e.id,'.Dropdown-module-container--AspYS{position:relative}.Dropdown-module-selectContainer--ZJPoy{position:relative;display:flex;border-radius:5px;transition:background-color 250ms ease, box-shadow 250ms ease}.Dropdown-module-light--jXZli .Dropdown-module-selectContainer--ZJPoy{background-color:rgba(255,255,255,.3);box-shadow:0 0 1px rgba(0,0,0,.3),0 0 2px rgba(33,33